/**
 * Sydney's suburbs, as the state gazettes them.
 *
 * Generated by scripts/fetch-suburbs.py from NSW Spatial Services' NSW
 * Administrative Boundaries Theme (layer 2, Suburb) — 498 suburbs inside the
 * 30 km disc the parking dataset covers, each with the postcode, the centre of
 * its own road network and the bounding box of those roads.
 *
 * The centre is deliberately *not* the polygon centroid. Palm Beach's centroid
 * sits in Pittwater and Mosman's in the harbour; a search result has to fly
 * the map to where the streets are, so the centre is the mean of the suburb's
 * street midpoints and the box is the box around them.
 *
 * 82 KB, so it is bundled rather than fetched — it has to be ready before the
 * first keystroke, and it is two orders of magnitude smaller than the street
 * data that already loads first.
 */

import raw from '../data/suburbs.json';

export interface Suburb {
  name: string;
  /** Australia Post postcode, as gazetted. The join key for Opal bus taps. */
  postcode: number | null;
  latitude: number;
  longitude: number;
  /** [west, south, east, north] around the suburb's own streets. */
  bbox: [number, number, number, number];
  /** Street segments in the suburb. */
  streets: number;
  /** How many of those carry published rules. */
  classified: number;
}

interface RawSuburb {
  name: string;
  postcode: number | null;
  lat: number;
  lon: number;
  bbox: number[];
  streets: number;
  classified: number;
}

export const SUBURBS: Suburb[] = (raw as { suburbs: RawSuburb[] }).suburbs.map((s) => ({
  name: s.name,
  postcode: s.postcode ?? null,
  latitude: s.lat,
  longitude: s.lon,
  bbox: [s.bbox[0], s.bbox[1], s.bbox[2], s.bbox[3]],
  streets: s.streets,
  classified: s.classified,
}));

const byName = new Map<string, Suburb>();
for (const s of SUBURBS) byName.set(s.name.toLowerCase(), s);

export function suburbByName(name: string | undefined): Suburb | undefined {
  return name ? byName.get(name.toLowerCase()) : undefined;
}

/**
 * Colloquial names people actually type, mapped to the gazetted suburb they
 * mean. Kept short on purpose: this is a list of things the official names
 * genuinely don't answer, not a second place database.
 */
export const ALIASES: Record<string, string> = {
  'sydney cbd': 'Sydney',
  cbd: 'Sydney',
  city: 'Sydney',
  'the city': 'Sydney',
  'town hall': 'Sydney',
  'circular quay': 'Sydney',
  'the rocks': 'Millers Point',
  'kings cross': 'Potts Point',
  'the spit': 'Mosman',
  'manly beach': 'Manly',
  'coogee beach': 'Coogee',
  'cronulla beach': 'Cronulla',
  'olympic park': 'Sydney Olympic Park',
};
